int main(){mgt_cuda::CudaMlpShape s{2,4,3,2,1,1};mgt::BatchNormTrainingPlan p;if(mgt::BuildBatchNormTrainingPlan(3,2,3,2,1,4,&p)!=mgt::Status::kOk)return 1;auto bn=mgt::InitializeBatchNormTrainingState(p);std::uint64_t params=50;std::vector<float>w(params);for(std::size_t i=0;i<w.size();i++)w[i]=.03f*static_cast<float>(static_cast<int>(i%9)-4);mgt::TrainStateStorage states[4]{};for(unsigned r=0;r<4;r++){states[r].v[0]=r;states[r].v[1]=(r+1)%4;}float labels[4]={1.f,3.f,-1.f,2.f};float *dw,*da,*dr,*dout,*dwork,*dlabels,*dloss,*dgrad,*ddy,*dfinal;cudaMalloc(&dw,w.size()*sizeof(float));cudaMalloc(&da,bn.affine.size()*sizeof(float));cudaMalloc(&dr,bn.running.size()*sizeof(float));cudaMalloc(&dout,4*sizeof(float));auto wf=mgt_cuda::MlpBatchNormForwardWorkspaceFloats(s,p,4);cudaMalloc(&dwork,wf*sizeof(float));cudaMalloc(&dlabels,sizeof(labels));cudaMalloc(&dloss,sizeof(float));cudaMalloc(&dgrad,params*sizeof(float));cudaMalloc(&ddy,4*sizeof(float));cudaMalloc(&dfinal,8*sizeof(float));cudaMemcpy(dw,w.data(),w.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(da,bn.affine.data(),bn.affine.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(dr,bn.running.data(),bn.running.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(dlabels,labels,sizeof(labels),cudaMemcpyHostToDevice);cudaMemset(dgrad,0,params*sizeof(float));mgt::TrainStateStorage* ds;cudaMalloc(&ds,sizeof(states));cudaMemcpy(ds,states,sizeof(states),cudaMemcpyHostToDevice);mgt_cuda::NcclRankContext*ctx=nullptr;cublasHandle_t blas=nullptr;if(mgt_cuda::CreateNcclSingleRankContext(0,&ctx)!=mgt::Status::kOk||cublasCreate(&blas)!=CUBLAS_STATUS_SUCCESS)return 1;if(mgt_cuda::LaunchMlpBatchNormForward(s,3,2,dw,da,dr,ds,4,4,dout,dwork,wf,p,ctx,blas,0)!=mgt::Status::kOk)return 1;float*final_activation=dwork+4*s.hd1+static_cast<std::uint64_t>(s.residual_blocks)*4*s.hd2;if(mgt_cuda::LaunchMlpBatchNormOutputLossGrad(s,dw,dlabels,dout,final_activation,4,4,dloss,dgrad,ddy,dfinal,ctx,blas,0)!=mgt::Status::kOk||cudaDeviceSynchronize()!=cudaSuccess)return 1;float loss=0,grad[3]{};cudaMemcpy(&loss,dloss,sizeof(float),cudaMemcpyDeviceToHost);cudaMemcpy(grad,dgrad+47,3*sizeof(float),cudaMemcpyDeviceToHost);const float expected_grad[3]={.6510818601f,.6067388058f,-2.5804600716f};if(std::fabs(loss-3.6869926453f)>3e-5f)return 1;for(int i=0;i<3;i++)if(std::fabs(grad[i]-expected_grad[i])>3e-5f)return 1;cublasDestroy(blas);return mgt_cuda::DestroyNcclRankContext(ctx)==mgt::Status::kOk?0:1;}